<?php
require_once __DIR__.'/../../includes/functions.php';require_admin();$error='';$notice='';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$action=(string)($_POST['action']??'');$id=filter_var($_POST['id']??null,FILTER_VALIDATE_INT);if($action==='delete'&&$id){$uses=db()->prepare('SELECT COUNT(*) FROM coupon_usage WHERE coupon_id=?');$uses->execute([$id]);if((int)$uses->fetchColumn())$error='Coupons with order history cannot be deleted; deactivate them instead.';else{db()->prepare('DELETE FROM coupons WHERE id=?')->execute([$id]);$notice='Coupon deleted.';}}elseif(in_array($action,['create','update'],true)){$code=strtoupper(trim((string)($_POST['code']??'')));$type=(string)($_POST['discount_type']??'');$value=filter_var($_POST['discount_value']??null,FILTER_VALIDATE_FLOAT);$minimum=filter_var($_POST['minimum_order']??0,FILTER_VALIDATE_FLOAT);$limit=trim((string)($_POST['usage_limit']??''));$limit=$limit===''?null:filter_var($limit,FILTER_VALIDATE_INT);$starts=trim((string)($_POST['starts_at']??''))?:null;$expires=trim((string)($_POST['expires_at']??''))?:null;$active=isset($_POST['is_active'])?1:0;if(!preg_match('/^[A-Z0-9_-]{3,40}$/',$code)||!in_array($type,['fixed','percent'],true)||$value===false||$value<0||($type==='percent'&&$value>100)||$minimum===false||$minimum<0||($limit!==null&&($limit===false||$limit<1))||($starts&&$expires&&$starts>$expires))$error='Check the coupon code, discount, minimum, limit and dates.';else{try{if($action==='create')db()->prepare('INSERT INTO coupons (code,discount_type,discount_value,minimum_order,usage_limit,starts_at,expires_at,is_active) VALUES (?,?,?,?,?,?,?,?)')->execute([$code,$type,$value,$minimum,$limit,$starts,$expires,$active]);elseif($id)db()->prepare('UPDATE coupons SET code=?,discount_type=?,discount_value=?,minimum_order=?,usage_limit=?,starts_at=?,expires_at=?,is_active=? WHERE id=?')->execute([$code,$type,$value,$minimum,$limit,$starts,$expires,$active,$id]);$notice='Coupon saved.';}catch(PDOException $exception){$error=$exception->getCode()==='23000'?'That coupon code already exists.':'Coupon could not be saved.';error_log('Coupon save failed: '.$exception->getMessage());}}}}
$editId=filter_input(INPUT_GET,'edit',FILTER_VALIDATE_INT);$edit=null;if($editId){$q=db()->prepare('SELECT * FROM coupons WHERE id=?');$q->execute([$editId]);$edit=$q->fetch()?:null;}$coupons=db()->query('SELECT c.*,COUNT(cu.order_id) AS uses FROM coupons c LEFT JOIN coupon_usage cu ON cu.coupon_id=c.id GROUP BY c.id ORDER BY c.id DESC')->fetchAll();$adminTitle='Coupons · Yucca Fabrics';require __DIR__.'/../../includes/admin-header.php';
?>
<h1 class="font-serif text-4xl">Coupons</h1><?php if($error||$notice): ?><p class="mt-4 rounded p-3 text-sm <?= $error?'bg-red-50 text-red-800':'bg-green-50 text-green-800' ?>"><?= e($error?:$notice) ?></p><?php endif; ?><section class="mt-7 bg-white p-5"><h2 class="font-serif text-2xl"><?= $edit?'Edit coupon':'Create a coupon' ?></h2><form method="post" class="mt-4 grid gap-3 sm:grid-cols-2"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="<?= $edit?'update':'create' ?>"><?php if($edit): ?><input type="hidden" name="id" value="<?= (int)$edit['id'] ?>"><?php endif; ?><label class="text-sm">Coupon code<input class="form-control mt-1 uppercase" name="code" maxlength="40" required value="<?= e($edit['code']??'') ?>"></label><label class="text-sm">Discount type<select class="form-control mt-1" name="discount_type"><option value="percent" <?= ($edit['discount_type']??'percent')==='percent'?'selected':'' ?>>Percent</option><option value="fixed" <?= ($edit['discount_type']??'')==='fixed'?'selected':'' ?>>Fixed amount</option></select></label><label class="text-sm">Discount value<input class="form-control mt-1" name="discount_value" type="number" step=".01" min="0" required value="<?= e($edit['discount_value']??'') ?>"></label><label class="text-sm">Minimum order<input class="form-control mt-1" name="minimum_order" type="number" step=".01" min="0" value="<?= e($edit['minimum_order']??0) ?>"></label><label class="text-sm">Usage limit (optional)<input class="form-control mt-1" name="usage_limit" type="number" min="1" value="<?= e($edit['usage_limit']??'') ?>"></label><label class="text-sm">Start date/time<input class="form-control mt-1" name="starts_at" type="datetime-local" value="<?= !empty($edit['starts_at'])?e(date('Y-m-d\TH:i',strtotime($edit['starts_at']))):'' ?>"></label><label class="text-sm">Expiry date/time<input class="form-control mt-1" name="expires_at" type="datetime-local" value="<?= !empty($edit['expires_at'])?e(date('Y-m-d\TH:i',strtotime($edit['expires_at']))):'' ?>"></label><label class="flex items-center gap-2 text-sm"><input type="checkbox" name="is_active" <?= !isset($edit['is_active'])||$edit['is_active']?'checked':'' ?>> Active</label><div class="flex gap-4"><button class="rounded-full bg-forest px-5 py-2 text-sm text-white">Save coupon</button><?php if($edit): ?><a href="<?= e(url('admin/coupons/index.php')) ?>" class="self-center text-sm underline">Cancel</a><?php endif; ?></div></form></section><section class="mt-7 space-y-3"><?php foreach($coupons as $coupon): ?><article class="flex flex-wrap items-center justify-between gap-4 bg-white p-5"><div><p class="font-semibold"><?= e($coupon['code']) ?> <span class="ml-2 text-xs font-normal text-gray-500"><?= (int)$coupon['uses'] ?> uses</span></p><p class="mt-1 text-sm text-gray-600"><?= $coupon['discount_type']==='percent'?e($coupon['discount_value']).'%':e(money($coupon['discount_value'])) ?> off · minimum <?= e(money($coupon['minimum_order'])) ?> · <?= $coupon['is_active']?'Active':'Inactive' ?></p></div><div class="flex gap-4 text-sm"><a class="underline" href="?edit=<?= (int)$coupon['id'] ?>">Edit</a><?php if(!(int)$coupon['uses']): ?><form method="post" data-confirm="Delete this coupon?"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?= (int)$coupon['id'] ?>"><button class="text-red-700 underline">Delete</button></form><?php endif; ?></div></article><?php endforeach; ?></section>
